import java.util.List;

/**
 * This file is part of the Predator-Prey Simulation.
 *
 * An abstract plant organism present in the simulation.
 *
 * @version 2022.03.02
 */
public abstract class Plant extends Organism implements Growable, Consumable {

    // define fields
    private double size;
    private final int foodValue;
    private final boolean poisonous;
    private double growthRate;
    private double breedingProbability;

    /**
     * Constructor for a plant in the simulation.
     *
     * @param poisonous Whether the plant is poisonous or not.
     * @param foodValue The food value of this plant.
     * @param size The initial size of this plant.
     * @param randomAge Whether the animal should have a random age or not.
     * @param field The field in which the plant resides.
     * @param location The location in which the plant spawns into.
     */
    public Plant(boolean poisonous, int foodValue, double size, boolean randomAge, Field field, Location location) {
        super(randomAge, field, location);

        this.size = size;
        this.foodValue = foodValue;
        this.poisonous = poisonous;
    }

    /**
     * Abstract method for what the plant does, i.e. what is always run at every step.
     *
     * @param newPlants A list of all newborn plants in this simulation step.
     * @param weather The current state of weather in the simulation.
     * @param time The current state of time in the simulation.
     */
    @Override
    public void act(List<Organism> newPlants, Weather weather, TimeOfDay time) {
        if (isAlive()) {
            setBreedingProbability(getLowBreedingProbability());
            if (hasFavorableWeather(weather)) {
                setBreedingProbability(getHighBreedingProbability());
            }
            grow();
            giveBirth(newPlants);
        }
    }

    /**
     * Grow in size in accordance with the current growth rate.
     */
    @Override
    public void grow() {
        size = size*getGrowthRate() > getMaxSize() ? 1 : size*getGrowthRate();
        if (size == 0) {
            remove();
        }
    }

    /**
     * Getter method for rate of growth of this plant.
     *
     * @return A double representing growth rate.
     */
    @Override
    public double getGrowthRate() {
        return this.growthRate;
    }

    /**
     * Setter method for rate of growth of this plant.
     *
     * @param rate A given growth rate.
     */
    @Override
    public void setGrowthRate(double rate) {
        this.growthRate = rate;
    }

    /**
     * Get maximum size of the plant.
     *
     * @return A double representing maximum size.
     */
    @Override
    abstract public double getMaxSize();

    /**
     * Getter method for the maximum litter size of the plant's newborns.
     *
     * @return An integer value representing the maximum allowed litter size.
     */
    @Override
    abstract public int getMaxLitterSize();

    /**
     * Checks if the plant meets specified conditions in order to breed.
     *
     * @return Whether this plant can breed or not.
     */
    @Override
    protected boolean canBreed() {
        return getAge() >= getBreedingAge();
    }

    /**
     * Get the current size of the plant.
     *
     * @return A double representing current size.
     */
    @Override
    public double getSize() {
        return this.size;
    }

    /**
     * Getter method of the value of the food of this plant.
     *
     * @return An integer for the plant's food value.
     */
    @Override
    public int getFoodValue() {
        return this.foodValue;
    }

    /**
     * Setter method to clear this plant from the simulation
     * when it is eaten.
     */
    @Override
    public void setEaten() {
        clearFromField();
    }

    /**
     * Returns whether this plant is poisonous or not.
     * @return Whether this plant is poisonous or not.
     */
    @Override
    public boolean isPoisonous() {
        return this.poisonous;
    }

    /**
     * Setter  method for the probability to breed of the organism.
     *
     * @param probability A given double value representing the breeding probability.
     */
    protected void setBreedingProbability(double probability) {
        this.breedingProbability = probability;
    }

    /**
     * Getter method for the probability to breed of the organism.
     *
     * @return A double value representing the breeding probability.
     */
    @Override
    public double getBreedingProbability() {
        return this.breedingProbability;
    }

    protected abstract double getLowBreedingProbability();

    protected abstract double getHighBreedingProbability();

    protected abstract boolean hasFavorableWeather(Weather weather);
}

import java.util.List;
import java.util.Random;

/**
 * This file is part of the Predator-Prey Simulation.
 *
 * An abstract animal organism present in the simulation.
 *
 * @version 2022.03.02
 */
public abstract class Animal extends Organism implements AbleToEat {

    // define fields
    private final Gender gender; // gender of specific animal
    private boolean infected; // whether an animal has been infected or not

    // shared random generator to generate consistent results
    private static final Random rand = Randomizer.getRandom();

    /**
     * Constructor for an animal in the simulation.
     *
     * @param randomAge Whether the animal should have a random age or not.
     * @param field The field in which the animal resides.
     * @param location The location in which the animal spawns into.
     */
    public Animal(boolean randomAge, Field field, Location location) {
        super(randomAge, field, location);

        // randomly assign male or female
        this.gender = Gender.getRandom();
        this.infected = false;
    }

    /**
     * Abstract method for what the animal does, i.e. what is always run at every step.
     *
     * @param newAnimals A list of all newborn animals in this simulation step.
     * @param weather The current state of weather in the simulation.
     * @param time The current state of time in the simulation.
     */
    @Override
    abstract public void act(List<Organism> newAnimals, Weather weather, TimeOfDay time);

    /**
     * Called when a consumable food item may be eaten.
     *
     * @param consumable The item to be eaten.
     * @return Whether the item was eaten or not.
     */
    @Override
    abstract public boolean eat(Consumable consumable);

    /**
     * Checks all adjacent location for animals that meet specific
     * breeding conditions, and returns true if it is even possible.
     *
     * @return Whether this animal can breed or not.
     */
    @Override
    protected boolean canBreed() {
        if (getAge() < getBreedingAge() || getField() == null || getLocation() == null) {
            return false;
        }

        for (Location loc : getField().adjacentLocations(getLocation())) {
            Organism organism = getField().getOrganismAt(loc);
            if (organism != null && organism.getClass() == getClass()) {
                Animal animal = (Animal) organism;
                if (animal.isMale() != isMale()) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * Getter method returning the gender of this animal.
     *
     * @return The gender of the animal.
     */
    private Gender getGender() {
        return this.gender;
    }

    /**
     * Returns if the animal is a male or not.
     *
     * @return Whether the animal's gender is male or not.
     */
    protected boolean isMale() {
        return getGender() == Gender.MALE;
    }

    /**
     * Getter method returning whether the animal has been
     * infected or not.
     *
     * @return Whether the animal is infectious or not.
     */
    protected boolean isInfected() {
        return this.infected;
    }

    /**
     * Setter method to alter the infected field of this animal
     * to a given boolean.
     *
     * @param infected The value the infected field should be changed to.
     */
    private void setInfected(boolean infected) {
        this.infected = infected;
    }

    /**
     * Infects a given animal.
     *
     * @param animal The animal to infect.
     */
    protected void infect(Animal animal) {
        animal.setInfected(true);
    }

    /**
     * Find an animal in an adjacent location for this animal to infect.
     *
     * @return The location of a nearby animal that can be infected.
     */
    protected Location findAnimalToInfect() {
        if (!infected) {
            return null;
        }

        for (Location loc : getField().adjacentLocations(getLocation())) {
            Organism organism = getField().getOrganismAt(loc);
            if (organism instanceof Animal) {
                Animal animal = (Animal) organism;
                if (animal.isAlive() && (!animal.isInfected())) {
                    if (rand.nextDouble() <= 0.01) {
                        infect(animal);
                    }
                    return loc;
                }
            }
        }

        return null;
    }

    /**
     * Getter method to return this animal's disease spreading probability.
     *
     * @return The animal's disease spreading probability.
     */
    abstract protected double getDiseaseSpreadProbability();

    /**
     * Getter method to return the probability this animal dies from disease.
     *
     * @return The animal's disease death probability.
     */
    abstract protected double getDeathByDiseaseProbability();
}

import java.util.List;
import java.util.Random;

/**
 * This file is part of the Predator-Prey Simulation.
 *
 * An abstract class representing any organism in the simulation.
 *
 * @version 2022.03.02
 */
public abstract class Organism implements Entity {

    // define fields
    //number of steps an organism remains for after dying but not having been eaten
    private static final int LIFETIME_AFTER_DEATH = 40;
    private boolean alive;
    private boolean removed;
    private Field field;
    private Location location;
    private int howLongDead;

    private int age;

    // shared random generator to generate consistent results
    private static final Random rand = Randomizer.getRandom();

    /**
     * Constructor for an Organism in the simulation.
     *
     * @param randomAge Whether we assign this organism a random age or not.
     * @param field The field in which this organism resides.
     * @param location The location in which this organism is spawned into.
     */
    public Organism(boolean randomAge, Field field, Location location) {
        this.howLongDead = 0;
        alive = true;
        removed = false;
        this.field = field;
        setLocation(location);

        if (randomAge) {
            age = rand.nextInt(getMaxAge());
        } else {
            age = 0;
        }
    }

    /**
     * Abstract method for what an organism does, i.e. what is always run at every step.
     *
     * @param newOrganisms A list of all newborn organisms in this simulation step.
     * @param weather The current state of weather in the simulation.
     * @param time The current state of time in the simulation.
     */
    @Override
    abstract public void act(List<Organism> newOrganisms, Weather weather, TimeOfDay time);

    /**
     * Check whether the organism is alive or not.
     * @return true if the organism is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Removes the current organism from the field.
     */
    protected void remove() {
        setDead();
        clearFromField();
        removed = true;
    }

    /**
     * Return whether the current organism object is supposed
     * to be removed from the simulation.
     *
     * @return A boolean value representing if the organism has been removed or not.
     */
    public boolean isRemoved() {
        return removed;
    }

    /**
     * Indicate that the organism is no longer alive.
     */
    protected void setDead()
    {
        alive = false;
    }

    /**
     * Return the organism's location.
     * @return The organism's location.
     */
    protected Location getLocation()
    {
        return this.location;
    }

    /**
     * Place the organism at the new location in the given field.
     * @param newLocation The organism's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * Set the organism's location to a null value directly.
     */
    protected void setLocationToNull() {
        location = null;
    }

    /**
     * Detach this organism from its current field position without
     * changing its alive/removed lifecycle flags.
     */
    protected void clearFromField() {
        if(location != null && field != null) {
            field.clear(location);
        }
        location = null;
        field = null;
    }

    /**
     * Return the organism's field.
     * @return The organism's field.
     */
    protected Field getField()
    {
        return this.field;
    }

    /**
     * Getter method for the probability to breed of the organism.
     *
     * @return A double value representing the breeding probability.
     */
    abstract public double getBreedingProbability();

    /**
     * Getter method for the maximum litter size of the organism's newborns.
     *
     * @return An integer value representing the maximum allowed litter size.
     */
    abstract public int getMaxLitterSize();

    /**
     * Getter method for the maximum age of the organism.
     *
     * @return An integer value representing the maximum age.
     */
    abstract public int getMaxAge();

    /**
     * Getter method for the age of breeding of the organism.
     *
     * @return A double value representing the breeding age.
     */
    abstract public int getBreedingAge();

    /**
     * Called when breeding occurs for this organism.
     *
     * @return The number of births as a result of breeding.
     */
    protected int breed() {
        int births = 0;
        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
            births = rand.nextInt(getMaxLitterSize()) + 1;
        }
        return births;
    }

    /**
     * Create a new instance of this organism.
     * @param field The field in which the spawn will reside in.
     * @param location The location in which the spawn will occupy.
     * @return A new Organism instance.
     */
    abstract protected Organism createNewOrganism(Field field, Location location);

    /**
     * Check whether or not this organism is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newOrganisms A list to return newly born organisms.
     */
    protected void giveBirth(List<Organism> newOrganisms) {
        // New organisms are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            newOrganisms.add(createNewOrganism(field, loc));
        }
    }

    /**
     * Checks all adjacent location for organisms that meet specific
     * breeding conditions, and returns true if it is even possible.
     *
     * @return Whether this organism can breed or not.
     */
    abstract protected boolean canBreed();

    /**
     * Increase the age.
     * This could result in the organisms death.
     */
    protected void incrementAge()
    {
        age++;

        if (age > getMaxAge()) {
            //setDead();
            remove();
        }
    }

    /**
     * Getter method for the current age of this organism.
     *
     * @return An integer value representing age.
     */
    protected int getAge() {
        return this.age;
    }

    /**
     * Setter method for the field in which this organism resides.
     * @param field The field where the organism is located.
     */
    protected void setField(Field field) {
        this.field = field;
    }

    /**
     * Prevents overcrowding of dead animals
     * Remove the organism from the field after being dead for a s
     * specified number of steps and not being eaten.
     */
    protected void decayifDead() {
        this.howLongDead++;
        if (this.howLongDead > LIFETIME_AFTER_DEATH){
            remove();
        }
    }
}

