 11	public abstract class Organism implements Entity {
 12	
 13	    // define fields
 14	    //number of steps an organism remains for after dying but not having been eaten
 15	    private static final int LIFETIME_AFTER_DEATH = 40;
 16	    private boolean alive;
 17	    private boolean removed;
 18	    private Field field;
 19	    private Location location;
 20	    private int howLongDead;
 21	    private final OrganismAttributes attributes;
 22	    private final OrganismFactory offspringFactory;
 23	
 24	    private int age;
 25	
 26	    // shared random generator to generate consistent results
 27	    private static final Random rand = Randomizer.getRandom();
 28	
 29	    /**
 30	     * Constructor for an Organism in the simulation.
 31	     *
 32	     * @param randomAge Whether we assign this organism a random age or not.
 33	     * @param field The field in which this organism resides.
 34	     * @param location The location in which this organism is spawned into.
 35	     */
 36	    public Organism(boolean randomAge, Field field, Location location,
 37	                    OrganismAttributes attributes, OrganismFactory offspringFactory) {
 38	        this.howLongDead = 0;
 39	        alive = true;
 40	        removed = false;
 41	        this.field = field;
 42	        this.attributes = attributes;
 43	        this.offspringFactory = offspringFactory;
 44	        setLocation(location);
 45	
 46	        if (randomAge) {
 47	            age = rand.nextInt(attributes.getMaxAge());
 48	        } else {
 49	            age = 0;
 50	        }
 51	    }
 52	
 53	    /**
 54	     * Abstract method for what an organism does, i.e. what is always run at every step.
 55	     *
 56	     * @param newOrganisms A list of all newborn organisms in this simulation step.
 57	     * @param weather The current state of weather in the simulation.
 58	     * @param time The current state of time in the simulation.
 59	     */
 60	    @Override
 61	    abstract public void act(List<Organism> newOrganisms, Weather weather, TimeOfDay time);
 62	
 63	    /**
 64	     * Check whether the organism is alive or not.
 65	     * @return true if the organism is still alive.
 66	     */
 67	    protected boolean isAlive()
 68	    {
 69	        return alive;
 70	    }
 71	
 72	    /**
 73	     * Removes the current organism from the field.
 74	     */
 75	    protected void remove() {
 76	        setDead();
 77	        clearFromField();
 78	        removed = true;
 79	    }
 80	
 81	    /**
 82	     * Return whether the current organism object is supposed
 83	     * to be removed from the simulation.
 84	     *
 85	     * @return A boolean value representing if the organism has been removed or not.
 86	     */
 87	    public boolean isRemoved() {
 88	        return removed;
 89	    }
 90	
 91	    /**
 92	     * Indicate that the organism is no longer alive.
 93	     */
 94	    protected void setDead()
 95	    {
 96	        alive = false;
 97	    }
 98	
 99	    /**
100	     * Return the organism's location.
101	     * @return The organism's location.
102	     */
103	    protected Location getLocation()
104	    {
105	        return this.location;
106	    }
107	
108	    /**
109	     * Place the organism at the new location in the given field.
110	     * @param newLocation The organism's new location.
111	     */
112	    protected void setLocation(Location newLocation)
113	    {
114	        if(location != null) {
115	            field.clear(location);
116	        }
117	        location = newLocation;
118	        field.place(this, newLocation);
119	    }
120	
121	    /**
122	     * Set the organism's location to a null value directly.
123	     */
124	    protected void setLocationToNull() {
125	        location = null;
126	    }
127	
128	    /**
129	     * Detach this organism from its current field position without
130	     * changing its alive/removed lifecycle flags.
131	     */
132	    protected void clearFromField() {
133	        if(location != null && field != null) {
134	            field.clear(location);
135	        }
136	        location = null;
137	        field = null;
138	    }
139	
140	    /**
141	     * Return the organism's field.
142	     * @return The organism's field.
143	     */
144	    protected Field getField()
145	    {
146	        return this.field;
147	    }
148	
149	    /**
150	     * Getter method for the probability to breed of the organism.
151	     *
152	     * @return A double value representing the breeding probability.
153	     */
154	    abstract public double getBreedingProbability();
155	
156	    public int getMaxLitterSize() {
157	        return attributes.getMaxLitterSize();
158	    }
159	
160	    public int getMaxAge() {
161	        return attributes.getMaxAge();
162	    }
163	
164	    public int getBreedingAge() {
165	        return attributes.getBreedingAge();
166	    }
167	
168	    /**
169	     * Called when breeding occurs for this organism.
170	     *
171	     * @return The number of births as a result of breeding.
172	     */
173	    protected int breed() {
174	        int births = 0;
175	        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
176	            births = rand.nextInt(getMaxLitterSize()) + 1;
177	        }
178	        return births;
179	    }
180	
181	    /**
182	     * Check whether or not this organism is to give birth at this step.
183	     * New births will be made into free adjacent locations.
184	     * @param newOrganisms A list to return newly born organisms.
185	     */
186	    protected void giveBirth(List<Organism> newOrganisms) {
187	        // New organisms are born into adjacent locations.
188	        // Get a list of adjacent free locations.
189	        Field field = getField();
190	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
191	        int births = breed();
192	        for(int b = 0; b < births && free.size() > 0; b++) {
193	            Location loc = free.remove(0);
194	            newOrganisms.add(offspringFactory.create(true, field, loc));
195	        }
196	    }
197	
198	    /**
199	     * Checks all adjacent location for organisms that meet specific
200	     * breeding conditions, and returns true if it is even possible.
201	     *
202	     * @return Whether this organism can breed or not.
203	     */
204	    abstract protected boolean canBreed();
205	
