207	     * Increase the age.
208	     * This could result in the organisms death.
209	     */
210	    protected void incrementAge()
211	    {
212	        age++;
213	
214	        if (age > getMaxAge()) {
215	            //setDead();
216	            remove();
217	        }
218	    }
