220	    /**
221	     * Getter method for the current age of this organism.
222	     *
223	     * @return An integer value representing age.
224	     */
225	    protected int getAge() {
226	        return this.age;
227	    }
228	
229	    /**
230	     * Setter method for the field in which this organism resides.
231	     * @param field The field where the organism is located.
232	     */
233	    protected void setField(Field field) {
234	        this.field = field;
235	    }
236	
237	    /**
238	     * Prevents overcrowding of dead animals
239	     * Remove the organism from the field after being dead for a s
240	     * specified number of steps and not being eaten.
241	     */
242	    protected void decayifDead() {
243	        this.howLongDead++;
244	        if (this.howLongDead > LIFETIME_AFTER_DEATH){
245	            remove();
246	        }
247	    }
248	}

