11	public abstract class Hunter extends Animal {
12	
13	    private static final Random rand = Randomizer.getRandom();
14	
15	    private int foodLevel;
16	
17	    /**
18	     * Constructor for a hunter in the simulation.
19	     *
20	     * @param foodLevel The food level of this hunter.
21	     * @param randomAge Whether the hunter should have a random age or not.
22	     * @param field The field in which the hunter resides.
23	     * @param location The location in which the hunter spawns into.
24	     */
25	    public Hunter(HunterAttributes attributes, boolean randomAge, Field field,
26	                  Location location, OrganismFactory offspringFactory) {
27	        super(attributes, randomAge, field, location, offspringFactory);
28	        this.foodLevel = attributes.getInitialFoodLevel();
29	    }
30	
31	    @Override
32	    public void act(List<Organism> newHunters, Weather weather, TimeOfDay time) {
33	        incrementAge();
34	        incrementHunger();
35	        if(isAlive()) {
36	            giveBirth(newHunters);
37	
38	            if (isRestingTime(time)) {
39	                return;
40	            }
41	
42	            if (rand.nextDouble() <= getDeathByDiseaseProbability() ) {
43	                remove();
44	                return;
45	            }
46	
47	            Location newLocation = chooseTargetLocation();
48	            if(newLocation == null) {
49	                newLocation = getField().freeAdjacentLocation(getLocation());
50	            }
51	
52	            if(newLocation != null) {
53	                setLocation(newLocation);
54	            }
55	            else {
56	                remove();
57	            }
58	        }
59	    }
60	
61	    /**
62	     * Increase the hunter's food level by a given integer amount.
63	     *
64	     * @param foodLevel The value to increment food level by.
65	     */
66	    protected void incrementFoodLevel(int foodLevel) {
67	        this.foodLevel += foodLevel;
68	    }
69	
70	    /**
71	     * Make this hunter more hungry. This could result in the hunter's death.
72	     */
73	    protected void incrementHunger() {
74	        foodLevel--;
75	        if (foodLevel <= 0) {
76	            remove();
77	        }
78	    }
79	
80	    private Location chooseTargetLocation() {
81	        if (rand.nextDouble() <= getDiseaseSpreadProbability()) {
82	            return findAnimalToInfect();
83	        }
84	        return findFood();
85	    }
86	
87	    protected abstract boolean isRestingTime(TimeOfDay time);
88	}

