 29	                  Location location, OrganismFactory offspringFactory) {
 30	        super(randomAge, field, location, attributes, offspringFactory);
 31	        this.attributes = attributes;
 32	
 33	        // randomly assign male or female
 34	        this.gender = Gender.getRandom();
 35	        this.infected = false;
 36	    }
 37	
 38	    /**
 39	     * Abstract method for what the animal does, i.e. what is always run at every step.
 40	     *
 41	     * @param newAnimals A list of all newborn animals in this simulation step.
 42	     * @param weather The current state of weather in the simulation.
 43	     * @param time The current state of time in the simulation.
 44	     */
 45	    @Override
 46	    abstract public void act(List<Organism> newAnimals, Weather weather, TimeOfDay time);
 47	
 48	    /**
 49	     * Called when a consumable food item may be eaten.
 50	     *
 51	     * @param consumable The item to be eaten.
 52	     * @return Whether the item was eaten or not.
 53	     */
 54	    @Override
