 57	    /**
 58	     * Checks all adjacent location for animals that meet specific
 59	     * breeding conditions, and returns true if it is even possible.
 60	     *
 61	     * @return Whether this animal can breed or not.
 62	     */
 63	    @Override
 64	    protected boolean canBreed() {
 65	        if (getAge() < getBreedingAge() || getField() == null || getLocation() == null) {
 66	            return false;
 67	        }
 68	
 69	        for (Location loc : getField().adjacentLocations(getLocation())) {
 70	            Organism organism = getField().getOrganismAt(loc);
 71	            if (organism != null && organism.getClass() == getClass()) {
 72	                Animal animal = (Animal) organism;
 73	                if (animal.isMale() != isMale()) {
 74	                    return true;
 75	                }
 76	            }
 77	        }
