  6	/**
  7	 * This file is part of the Predator-Prey Simulation.
  8	 *
  9	 * A populator for the field in the simulation.
 10	 *
 11	 * @version 2022.03.02
 12	 */
 13	public class Populator {
 14	
 15	    // define fields
 16	    private static final double ANIMAL_CREATION_PROBABILITY = 0.05;
 17	    private static final double PLANT_CREATION_PROBABILITY = 0.04;
 18	
 19	    private final List<SpawnRule> spawnRules;
 20	
 21	    /**
 22	     * Constructor for the populator.
 23	     *
 24	     * @param view A given SimulatorView.
 25	     */
 26	    public Populator(SimulatorView view) {
 27	        spawnRules = Arrays.asList(
 28	                new SpawnRule(Lion.class, Color.RED, ANIMAL_CREATION_PROBABILITY,
 29	                        (field, location) -> new Lion(true, field, location)),
 30	                new SpawnRule(Zebra.class, Color.BLUE, ANIMAL_CREATION_PROBABILITY,
 31	                        (field, location) -> new Zebra(true, field, location)),
 32	                new SpawnRule(Vulture.class, Color.ORANGE, ANIMAL_CREATION_PROBABILITY,
 33	                        (field, location) -> new Vulture(true, field, location)),
 34	                new SpawnRule(Grass.class, Color.GREEN, PLANT_CREATION_PROBABILITY,
 35	                        (field, location) -> new Grass(true, field, location)),
 36	                new SpawnRule(Goat.class, Color.PINK, ANIMAL_CREATION_PROBABILITY,
 37	                        (field, location) -> new Goat(true, field, location)),
 38	                new SpawnRule(Elephant.class, Color.GRAY, ANIMAL_CREATION_PROBABILITY,
 39	                        (field, location) -> new Elephant(true, field, location)),
 40	                new SpawnRule(Cheetah.class, Color.MAGENTA, ANIMAL_CREATION_PROBABILITY,
 41	                        (field, location) -> new Cheetah(true, field, location)),
 42	                new SpawnRule(PoisonBerry.class, Color.BLACK, PLANT_CREATION_PROBABILITY,
 43	                        (field, location) -> new PoisonBerry(true, field, location))
 44	        );
 45	
 46	        for (SpawnRule spawnRule : spawnRules) {
 47	            view.setColor(spawnRule.getOrganismType(), spawnRule.getColor());
 48	        }
 49	    }
 50	
 51	    /**
 52	     * Randomly populate the field with foxes and rabbits.
 53	     */
 54	    public void populate(List<Organism> organisms, Field field)
 55	    {
 56	        Random rand = Randomizer.getRandom();
 57	        field.clear();
 58	        for(int row = 0; row < field.getDepth(); row++) {
 59	            for(int col = 0; col < field.getWidth(); col++) {
 60	                populateLocation(organisms, field, row, col, rand);
 61	            }
 62	        }
 63	    }
 64	
 65	    private void populateLocation(List<Organism> organisms, Field field, int row, int col, Random rand) {
 66	        Location location = new Location(row, col);
 67	        for (SpawnRule spawnRule : spawnRules) {
 68	            if (rand.nextDouble() <= spawnRule.getCreationProbability()) {
 69	                organisms.add(spawnRule.spawn(field, location));
 70	                return;
 71	            }
 72	        }
 73	    }
 74	
 75	    private interface SpawnFactory {
 76	        Organism create(Field field, Location location);
 77	    }
 78	
 79	    private static class SpawnRule {
 80	        private final Class<? extends Organism> organismType;
 81	        private final Color color;
 82	        private final double creationProbability;
 83	        private final SpawnFactory spawnFactory;
 84	
 85	        private SpawnRule(Class<? extends Organism> organismType, Color color,
 86	                          double creationProbability, SpawnFactory spawnFactory) {
 87	            this.organismType = organismType;
 88	            this.color = color;
 89	            this.creationProbability = creationProbability;
 90	            this.spawnFactory = spawnFactory;
 91	        }
 92	
 93	        private Class<? extends Organism> getOrganismType() {
 94	            return organismType;
 95	        }
 96	
 97	        private Color getColor() {
 98	            return color;
 99	        }
100	
101	        private double getCreationProbability() {
102	            return creationProbability;
103	        }
104	
105	        private Organism spawn(Field field, Location location) {
106	            return spawnFactory.create(field, location);
107	        }
108	    }
109	}

